from pathlib import Path
import sys
root=Path(sys.argv[1]) if len(sys.argv)>1 else Path('.build/riftbound-standalone')
js_path=root/'assets/page-F6OuavDb.js'; css_path=root/'assets/riftbound.css'
s=js_path.read_text(); css=css_path.read_text()
marker='/* Riftbound Armory Virtualization V16.5 */'
if marker in s: raise SystemExit('V16.5 already applied')

def rep(old,new,label,count=1):
    global s
    n=s.count(old)
    if n!=count: raise SystemExit(f'V16.5 {label}: expected {count}, found {n}')
    s=s.replace(old,new,count)

